import{_ as t,c as o,o as s,d as a}from"./chunks/framework.NKWon0wL.js";const i="/uikit/images/atomic_design.png",h=JSON.parse('{"title":"Design","description":"","frontmatter":{"title":"Design"},"headers":[],"relativePath":"guide/design.md","filePath":"guide/design.md"}'),n={name:"guide/design.md"};function r(l,e,m,c,d,g){return s(),o("div",null,e[0]||(e[0]=[a('<h3 id="design-methodology" tabindex="-1">Design Methodology <a class="header-anchor" href="#design-methodology" aria-label="Permalink to &quot;Design Methodology&quot;">​</a></h3><p>Our UIkit library is primarily based on the principles of <a href="https://atomicdesign.bradfrost.com/chapter-2/" target="_blank" rel="noreferrer">Atomic Design</a>. This methodology emphasizes building UI components from the ground up, starting with small, independent elements—referred to as <em>atoms</em>.</p><p>These atoms are then composed into more complex, reusable structures known as <em>molecules</em> and beyond, promoting scalability, consistency, and modularity throughout the design system.</p><p><img src="'+i+'" alt="Atomic Design" title="Atomic Design"></p><ol><li>Atoms include basic HTML elements like <a href="./.html">icons</a>, <a href="./.html">inputs</a>, <a href="./.html">buttons</a>,...</li><li>Molecules are simple groups of UI elements functioning together as a unit. Label, input and button can join together to create a search form molecule.</li><li>Organisms are complex UI components composed of groups of molecules and/or atoms and/or other organisms. Example: <a href="./.html">header</a></li><li>Templates are page-level objects that place components into a <a href="./.html">layout</a> and articulate the design’s underlying content structure.</li><li>Pages are specific instances of templates that show what a UI looks like with real representative content in place.</li></ol><p>Being able to <strong>reuse</strong> basic components is a huge advantage in atomic web design. Recycling atoms saves designers time while upholding consistent habits across all website pages.</p>',6)]))}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
